"""SC-900 part B: Microsoft security solutions (Azure infrastructure security, Defender for Cloud,
Microsoft Sentinel and Microsoft Defender XDR).

Part A (sc900_a.py) owns CATEGORIES. This file never defines CATEGORIES.
IDs: flashcards f101+, questions q101+/tf101+/msq101+, lessons that reference them.
"""

SEC = 'security'


def fc(n, front, back, detail):
    return {'id': f'f{n}', 'cat': SEC, 'front': front, 'back': back, 'detail': detail}


def mc(qid, question, options, correct, explanation, why=None):
    q = {'id': qid, 'cat': SEC, 'type': 'mc', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}
    if why:
        q['whyTested'] = why
    return q


def tf(qid, question, answer, explanation):
    return {'id': qid, 'cat': SEC, 'type': 'tf', 'question': question, 'answer': answer, 'explanation': explanation}


def ms(qid, question, options, correct, explanation):
    return {'id': qid, 'cat': SEC, 'type': 'ms', 'question': question, 'options': options, 'correct': correct, 'explanation': explanation}


